/* SPDX-License-Identifier: MIT; independent synthetic RPM/GLINK firmware model.
 * Golden packets are literal protocol vectors, not generated by the codec. */
#include "rpm_smd.h"
#include "rpm_mmio.h"
#undef NDEBUG
#include <assert.h>
#include <stdio.h>
#include <string.h>
#define TX 0x100u
#define RX 0x400u
#define RING 256u
static unsigned cases;
static uint32_t word(const uint8_t *p)
{ return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24; }
static void put(uint8_t *p,uint32_t n)
{ for(unsigned i=0;i<4;i++)p[i]=(uint8_t)(n>>(8*i)); }
struct fixture {
    uint8_t ram[DRE_RPM_MSG_RAM_BYTES];
    struct dre_rpm_votes state;
    unsigned reads,writes,notifications,leases,barriers;
    unsigned fail_read,fail_write,fail_notify,fail_lease;
    uint64_t ticks,epoch;
    unsigned version,requests;
    int drop_ack,foreign_ack,nack,malformed,wrong_channel,unknown_open,wrong_version,lose_on_vote;
    int clock_stuck,late_ack;
};
static uint32_t ramget(struct fixture *f,unsigned off)
{ assert(off%4==0 && off<=sizeof(f->ram)-4);return word(f->ram+off); }
static void ramput(struct fixture *f,unsigned off,uint32_t value)
{ assert(off%4==0 && off<=sizeof(f->ram)-4);put(f->ram+off,value); }
static void ring_read(struct fixture *f,unsigned off,unsigned pos,uint8_t *out,unsigned n)
{ for(unsigned i=0;i<n;i++)out[i]=f->ram[off+8+(pos+i)%RING]; }
static void remote_enqueue(struct fixture *f,const uint8_t *packet,unsigned bytes)
{
    unsigned head=ramget(f,RX+4),tail=ramget(f,RX),free=tail<=head?RING-head+tail:tail-head;
    assert(bytes%8==0 && bytes+8<=free);
    for(unsigned i=0;i<bytes;i++)f->ram[RX+8+(head+i)%RING]=packet[i];
    ramput(f,RX+4,(head+bytes)%RING);
}
static void remote_control(struct fixture *f,unsigned cmd,unsigned cid,uint32_t value)
{
    uint8_t packet[24]={0};put(packet,cmd|cid<<16);put(packet+4,value);
    unsigned bytes=8;
    if(cmd==2) { memcpy(packet+8,f->unknown_open?"not_rpm_name":"rpm_requests",13);bytes=24; }
    remote_enqueue(f,packet,bytes);
}
static void remote_ack(struct fixture *f,const uint8_t *request,unsigned bytes)
{
    assert(bytes==(f->version?40u:52u));
    unsigned h=f->version?16:28;uint32_t id=word(request+(f->version?4:8));
    assert(word(request+h)==0x6e657773 && word(request+h+4)==4 && word(request+h+8)==1);
    assert(word(request+h+12)==0x6c766c76 && word(request+h+16)==4 && word(request+h+20)>0);
    assert(word(request+(f->version?8:16))==0x78637772 || word(request+(f->version?8:16))==0x786d7772 || word(request+(f->version?8:16))==0x78677772);
    assert((f->version?(word(request+12)>>16)&0xfff:word(request+20))==0);
    f->requests++;
    if(f->drop_ack)return;
    uint8_t packet[144]={0},ack[64]={0};unsigned count;
    if(!f->version) {
        const uint8_t normal[]={0x72,0x65,0x71,0,12,0,0,0,0x6d,0x73,0x67,0x23,4,0,0,0,0,0,0,0};
        memcpy(ack,normal,sizeof(normal));put(ack+16,id+(f->foreign_ack?1:0));count=20;
        if(f->nack) { put(ack+4,28);put(ack+20,0x00727265);put(ack+24,8);memcpy(ack+28,"rejected",8);count=36; }
    } else {
        put(ack,f->nack?0x01040004:0x01030000);put(ack+4,id+(f->foreign_ack?1:0));count=f->nack?12:8;
        if(f->nack)put(ack+8,5);
    }
    if(f->malformed)ack[0]^=0x80;
    put(packet,9|((f->wrong_channel?8u:7u)<<16));put(packet+8,count);memcpy(packet+16,ack,count);
    remote_enqueue(f,packet,(16+count+7)&~7u);
    if(f->lose_on_vote)f->epoch++;
    if(f->late_ack)f->ticks+=1000000;
}
static int remote_notify(struct fixture *f)
{
    while(ramget(f,TX)!=ramget(f,TX+4)) {
        unsigned tail=ramget(f,TX);uint8_t packet[144]={0};ring_read(f,TX,tail,packet,8);
        unsigned cmd=word(packet)&65535,cid=word(packet)>>16,count=8;
        if(cmd==2)count=24;
        if(cmd==9) { ring_read(f,TX,tail,packet,16);count=(16+word(packet+8)+7)&~7u;assert(count<=sizeof(packet)); }
        ring_read(f,TX,tail,packet,count);ramput(f,TX,(tail+count)%RING);
        if(cmd==0) { assert(cid==1 && word(packet+4)==0);remote_control(f,0,1,0);remote_control(f,1,f->wrong_version?2:1,0); }
        else if(cmd==1)assert(cid==1 && word(packet+4)==0);
        else if(cmd==2) { assert(cid==1 && word(packet+4)==13 && !memcmp(packet+8,"rpm_requests",13));remote_control(f,2,7,13);remote_control(f,4,1,0); }
        else if(cmd==4)assert(cid==7);
        else if(cmd==9) { assert(cid==1 && !word(packet+4) && !word(packet+12));remote_ack(f,packet+16,word(packet+8)); }
        else assert(!"unexpected host GLINK command");
    }
    return 1;
}
static uint64_t lease(void *cookie)
{ struct fixture *f=cookie;f->leases++;return f->leases==f->fail_lease?0:f->epoch; }
static int read32(void *cookie,uint32_t offset,uint32_t *value)
{ struct fixture *f=cookie;f->reads++;if(f->reads==f->fail_read)return 0;*value=ramget(f,offset);return 1; }
static int write32(void *cookie,uint32_t offset,uint32_t value)
{
    struct fixture *f=cookie;f->writes++;
    assert(offset==TX+4 || offset==RX || (offset>=TX+8 && offset<TX+8+RING));
    ramput(f,offset,value); /* Fault is deliberately AFTER the possible store. */
    return f->writes!=f->fail_write;
}
static void barrier(void *cookie) { ((struct fixture *)cookie)->barriers++; }
static int notify(void *cookie)
{ struct fixture *f=cookie;f->notifications++;remote_notify(f);return f->notifications!=f->fail_notify; }
static uint64_t now(void *cookie)
{ struct fixture *f=cookie;if(!f->clock_stuck)f->ticks+=1000;return f->ticks; }
static struct dre_rpm_io io(struct fixture *f)
{ return (struct dre_rpm_io){lease,read32,write32,barrier,notify,now,f}; }
static struct dre_rpm_config config(unsigned version)
{ return (struct dre_rpm_config){DRE_RPM_MSG_RAM_BASE,DRE_RPM_MSG_RAM_BYTES,DRE_RPM_TIMER_HZ,15,version?1:0,version?DRE_RPM_PROTOCOL_V1:0}; }
static void resources(struct dre_rpm_resource r[3])
{
    /* Synthetic QUALIFIED plan, not physical voltage qualification. */
    r[0]=(struct dre_rpm_resource){0x78637772,0,16,512,(1u<<1)|(1u<<4)};
    r[1]=(struct dre_rpm_resource){0x786d7772,0,16,512,(1u<<1)|(1u<<4)};
    r[2]=(struct dre_rpm_resource){0x78677772,0,0,512,(1u<<1)|(1u<<4)};
}
static void init(struct fixture *f,unsigned version)
{
    memset(f,0,sizeof(*f));f->epoch=91;f->version=version;
    unsigned toc=DRE_RPM_MSG_RAM_BYTES-256;
    ramput(f,toc,0x67727430);ramput(f,toc+4,2);
    ramput(f,toc+8,0x61703272);ramput(f,toc+12,TX);ramput(f,toc+16,RING);
    ramput(f,toc+20,0x72326170);ramput(f,toc+24,RX);ramput(f,toc+28,RING);
    /* Nonzero empty positions force real wraparound; resetting to0 is wrong. */
    ramput(f,TX,240);ramput(f,TX+4,240);ramput(f,RX,248);ramput(f,RX+4,248);
}
static const char *open_fixture(struct fixture *f)
{
    struct dre_rpm_resource r[3];resources(r);struct dre_rpm_config c=config(f->version);struct dre_rpm_io o=io(f);
    return dre_rpm_votes_open(&f->state,&o,&c,r,1000000);
}
static const char *run(struct fixture *f)
{
    const char *result=open_fixture(f);if(strcmp(result,"RPM_ENDPOINT_OPEN"))return result;
    struct dre_rpm_io o=io(f);return dre_rpm_hold_level(&f->state,&o,0,64,1000000);
}
static int physical_read(void *cookie,uint64_t address,uint32_t *value)
{
    assert(address>=DRE_RPM_MSG_RAM_BASE && address<DRE_RPM_MSG_RAM_BASE+DRE_RPM_MSG_RAM_BYTES);
    return read32(cookie,(uint32_t)(address-DRE_RPM_MSG_RAM_BASE),value);
}
static int physical_write(void *cookie,uint64_t address,uint32_t value)
{
    if(address==DRE_RPM_IPCC_BASE+0x0c) { assert(value==0);return notify(cookie); }
    assert(address>=DRE_RPM_MSG_RAM_BASE && address<DRE_RPM_MSG_RAM_BASE+DRE_RPM_MSG_RAM_BYTES);
    return write32(cookie,(uint32_t)(address-DRE_RPM_MSG_RAM_BASE),value);
}
static void adapter_test(void)
{
    struct fixture f;struct dre_rpm_mmio m;struct dre_rpm_io out;
    struct dre_rpm_mmio_map map={DRE_RPM_MSG_RAM_BASE,DRE_RPM_IPCC_BASE,DRE_RPM_MSG_RAM_BYTES,DRE_RPM_IPCC_BYTES,0,0};
    init(&f,0);struct dre_rpm_mmio_ops ops={lease,physical_read,physical_write,barrier,now,&f};
    for(unsigned kind=0;kind<6;kind++) {
        struct dre_rpm_mmio_map bad=map;
        if(kind==0)bad.message_base++;
        if(kind==1)bad.ipcc_base++;
        if(kind==2)bad.message_bytes--;
        if(kind==3)bad.ipcc_bytes--;
        if(kind==4)bad.client_id=1;
        if(kind==5)bad.signal_id=2;
        assert(!dre_rpm_bind_mmio(&m,&ops,&bad,&out) && !f.reads && !f.writes && !f.notifications);cases++;
    }
    assert(dre_rpm_bind_mmio(&m,&ops,&map,&out) && !f.reads && !f.writes && !f.notifications);cases++;
    uint32_t value;assert(!out.read32(out.cookie,DRE_RPM_MSG_RAM_BYTES,&value));assert(!out.write32(out.cookie,3,0));cases++;
    struct dre_rpm_resource r[3];resources(r);struct dre_rpm_config cfg=config(0);
    assert(!strcmp(dre_rpm_votes_open(&f.state,&out,&cfg,r,1000000),"RPM_ENDPOINT_OPEN"));
    assert(!strcmp(dre_rpm_hold_level(&f.state,&out,2,16,1000000),"RPM_VOTE_ACKED") && f.notifications && f.state.held_level[2]==16);cases++;
    f.epoch++;assert(!out.notify(out.cookie));cases++;
}
static void partial_frame_test(void)
{
    struct fixture f;init(&f,0);assert(!strcmp(open_fixture(&f),"RPM_ENDPOINT_OPEN"));
    uint8_t packet[40]={0},out[128];put(packet,9|7u<<16);put(packet+8,20);
    const uint8_t ack[]={0x72,0x65,0x71,0,12,0,0,0,0x6d,0x73,0x67,0x23,4,0,0,0,2,0,0,0};memcpy(packet+16,ack,20);
    struct dre_rpm_io o=io(&f);size_t count=99;unsigned writes=f.writes;
    remote_enqueue(&f,packet,8);assert(!dre_rpm_glink_receive(&f.state.link,&o,out,sizeof(out),&count) && !count && f.writes==writes);cases++;
    remote_enqueue(&f,packet+8,8);assert(!dre_rpm_glink_receive(&f.state.link,&o,out,sizeof(out),&count) && f.writes==writes);cases++;
    remote_enqueue(&f,packet+16,24);assert(dre_rpm_glink_receive(&f.state.link,&o,out,sizeof(out),&count)==1 && count==20 && !memcmp(out,ack,20));cases++;
    assert(!f.state.held_level[0]); /* Delivery alone never establishes a vote. */
}
static void codec_tests(void)
{
    const uint8_t v0[]={0x72,0x65,0x71,0,44,0,0,0,2,0,0,0,0,0,0,0,0x72,0x77,0x63,0x78,0,0,0,0,24,0,0,0,
        0x73,0x77,0x65,0x6e,4,0,0,0,1,0,0,0,0x76,0x6c,0x76,0x6c,4,0,0,0,64,0,0,0};
    uint8_t output[128];assert(dre_rpm_encode_hold(0,2,0,64,output,sizeof(output))==sizeof(v0));assert(!memcmp(output,v0,sizeof(v0)));cases++;
    const uint8_t v1[]={36,0,0,1,3,0,0,0,0x72,0x77,0x6d,0x78,24,0,0,0,0x73,0x77,0x65,0x6e,4,0,0,0,1,0,0,0,0x76,0x6c,0x76,0x6c,4,0,0,0,16,0,0,0};
    assert(dre_rpm_encode_hold(1,3,1,16,output,sizeof(output))==sizeof(v1));assert(!memcmp(output,v1,sizeof(v1)));cases++;
    for(unsigned n=0;n<sizeof(v0);n++) { memset(output,0xa5,sizeof(output));assert(!dre_rpm_encode_hold(0,2,0,64,output,n));assert(output[0]==0xa5);cases++; }
    for(unsigned v=0;v<3;v++)for(unsigned rail=0;rail<4;rail++)for(unsigned level=0;level<=513;level++) {
        size_t n=dre_rpm_encode_hold(v,2,rail,level,output,sizeof(output));
        if(v>1 || rail>2 || level==0 || (level!=16 && level!=32 && level!=48 && level!=64 && level!=128 && level!=192 && level!=256 && level!=320 && level!=384 && level!=416 && level!=512))assert(!n);
        else assert(n==(v?40u:52u));
        cases++;
    }
    uint8_t ack[]={0x72,0x65,0x71,0,12,0,0,0,0x6d,0x73,0x67,0x23,4,0,0,0,2,0,0,0};uint32_t error;
    assert(dre_rpm_decode_ack(0,2,ack,sizeof(ack),&error)==1);assert(!error);cases++;
    for(unsigned n=0;n<sizeof(ack);n++) { assert(dre_rpm_decode_ack(0,2,ack,n,&error)<0);cases++; }
    for(unsigned n=0;n<16;n++) { ack[n]^=0x80;assert(dre_rpm_decode_ack(0,2,ack,sizeof(ack),&error)<0);ack[n]^=0x80;cases++; }
    ack[16]=3;assert(!dre_rpm_decode_ack(0,2,ack,sizeof(ack),&error));cases++;
    uint8_t ack1[]={0,0,3,1,2,0,0,0};assert(dre_rpm_decode_ack(1,2,ack1,sizeof(ack1),&error)==1);cases++;
    uint8_t nack1[]={4,0,4,1,2,0,0,0,5,0,0,0};assert(dre_rpm_decode_ack(1,2,nack1,sizeof(nack1),&error)==-2 && error==5);cases++;
    assert(dre_rpm_wire_version(0,0)==0 && dre_rpm_wire_version(1,0)==0 && dre_rpm_wire_version(1,DRE_RPM_PROTOCOL_V1)==1);
    assert(dre_rpm_wire_version(0,1)<0 && dre_rpm_wire_version(1,2)<0 && dre_rpm_wire_version(-1,0)<0);cases++;
    assert(!dre_rpm_level_mask(0) && !dre_rpm_level_mask(17) && dre_rpm_level_mask(16)==2 && dre_rpm_level_mask(512)==2048);cases++;
    assert(!dre_rpm_encode_hold(0,0,0,64,output,sizeof(output)) && !dre_rpm_encode_hold(0,1,0,64,output,sizeof(output)));cases++;
    for(unsigned n=0;n<sizeof(ack1);n++) { assert(dre_rpm_decode_ack(1,2,ack1,n,&error)<0);cases++; }
}
int main(void)
{
    codec_tests();adapter_test();partial_frame_test();struct fixture f;unsigned reads,writes,notes,leases;
    for(unsigned version=0;version<2;version++) {
        init(&f,version);assert(!strcmp(run(&f),"RPM_VOTE_ACKED"));assert(f.requests==1 && f.state.held_level[0]==64 && f.state.acked_id[0]==2 && !f.state.unsafe);cases++;
    }
    init(&f,0);assert(!strcmp(run(&f),"RPM_VOTE_ACKED"));reads=f.reads;writes=f.writes;notes=f.notifications;leases=f.leases;
    struct dre_rpm_io o=io(&f);unsigned before=f.writes;
    assert(!strcmp(dre_rpm_hold_level(&f.state,&o,0,16,1000000),"RPM_LEVEL_PLAN_REJECTED") && f.writes==before);cases++;
    assert(!strcmp(dre_rpm_hold_level(&f.state,&o,0,48,1000000),"RPM_LEVEL_PLAN_REJECTED") && f.writes==before);cases++;
    assert(!strcmp(dre_rpm_hold_level(&f.state,&o,2,0,1000000),"RPM_LEVEL_PLAN_REJECTED") && f.writes==before);cases++;
    assert(!strcmp(dre_rpm_hold_level(&f.state,&o,0,64,1000000),"RPM_VOTE_ACKED") && f.state.acked_id[0]==3);cases++;
    f.nack=1;assert(!strcmp(dre_rpm_hold_level(&f.state,&o,1,16,1000000),"RPM_NACK") && f.state.held_level[0]==64 && !f.state.held_level[1]);cases++;
    before=f.writes;assert(!strcmp(dre_rpm_hold_level(&f.state,&o,1,16,1000000),"RPM_RESET_REQUIRED") && f.writes==before);cases++;
    for(unsigned kind=0;kind<4;kind++)for(unsigned n=1;n<=(kind==0?reads:kind==1?writes:kind==2?notes:leases);n++) {
        init(&f,0);if(kind==0)f.fail_read=n;if(kind==1)f.fail_write=n;if(kind==2)f.fail_notify=n;if(kind==3)f.fail_lease=n;
        const char *result=run(&f);assert(strcmp(result,"RPM_VOTE_ACKED"));assert(!f.state.held_level[0] && !f.state.acked_id[0]);
        if(f.writes)assert(f.state.link.unsafe && !f.state.link.open);
        cases++;
    }
    for(unsigned kind=0;kind<11;kind++) {
        init(&f,0);switch(kind) { case 0:f.drop_ack=1;break;case 1:f.foreign_ack=1;break;case 2:f.nack=1;break;case 3:f.malformed=1;break;case 4:f.wrong_channel=1;break;case 5:f.unknown_open=1;break;case 6:f.wrong_version=1;break;case 7:f.lose_on_vote=1;break;case 8:ramput(&f,TX,232);break;case 9:f.drop_ack=1;f.clock_stuck=1;break;case 10:f.late_ack=1;break; }
        assert(strcmp(run(&f),"RPM_VOTE_ACKED"));assert(!f.state.held_level[0]);if(f.writes)assert(f.state.link.unsafe);cases++;
        if(kind==0)assert(f.state.pending && f.state.pending_id==2 && f.state.pending_rail==0 && f.state.pending_level==64);
    }
    for(unsigned kind=0;kind<8;kind++) {
        init(&f,0);unsigned toc=DRE_RPM_MSG_RAM_BYTES-256;
        switch(kind) { case 0:ramput(&f,toc,0);break;case 1:ramput(&f,toc+4,21);break;case 2:ramput(&f,toc+24,TX);break;case 3:ramput(&f,toc+16,0xfffffff8);break;case 4:ramput(&f,toc+20,0x61703272);break;case 5:ramput(&f,toc+24,DRE_RPM_MSG_RAM_BYTES-256);break;case 6:ramput(&f,TX+4,256);break;case 7:ramput(&f,RX+4,249);break; }
        assert(strcmp(open_fixture(&f),"RPM_ENDPOINT_OPEN") && !f.writes);cases++;
    }
    init(&f,0);struct dre_rpm_resource r[3];resources(r);r[0].type=0x65706d73;r[0].id=1;
    struct dre_rpm_config cfg=config(0);o=io(&f);
    assert(!strcmp(dre_rpm_votes_open(&f.state,&o,&cfg,r,1000000),"RPM_RESOURCE_PLAN_REJECTED") && !f.writes);cases++;
    for(unsigned kind=0;kind<7;kind++) {
        init(&f,0);resources(r);cfg=config(0);o=io(&f);
        if(kind==0)cfg.version_reg_present=-1;
        if(kind==1) { cfg.version_reg_present=1;cfg.version_register=0x1234; }
        if(kind==2)cfg.physical_base++;
        if(kind==3)cfg.timer_hz=24000000;
        if(kind==4)cfg.channel_type=1;
        if(kind==5)r[1].allowed_levels=0;
        if(kind==6)r[2].allowed_levels|=1;
        assert(strcmp(dre_rpm_votes_open(&f.state,&o,&cfg,r,1000000),"RPM_ENDPOINT_OPEN") && !f.writes);cases++;
    }
    printf("PASS %u synthetic production RPM codec/GLINK/vote cases; %u read/%u write/%u mailbox/%u lease fault positions; physical ACK/power unproven\n",cases,reads,writes,notes,leases);
    return 0;
}
